#include &lt;stdio.h&gt;
#include &lt;unistd.h&gt;

int main(){

    // create an array for file descriptors 
    // the file descriptors are integer references for the two sides of the pipe
    // fd[0] is for the read end of the pipe
    // fd[1] is for the write end of the pipe
    int fd[2]; 

    // provide fd to the pipe() function to create the pipe
    pipe(fd); // returns 0 on success

    pid_t pid = fork();

    if (pid == 0){
        // Child Process - writing to pipe here

        // close the read end since we are writing here
        close(fd[0]);    

        // prompt for data
        int x;
        printf("Child: Give me an int: \n");
        scanf("%d", &x);

        // write the data to the pipe
        write(fd[1], &x, sizeof(int)); 

        // close the write end
        close(fd[1]);   

    } else {
        // Parent Process  - reading here

        // close the write end (since we are reading here)
        close(fd[1]);

        // read the data from the pipe
        int y;
        read(fd[0], &y, sizeof(int)); 
        printf("Parent: Received from child: %d\n", y);

        // close the read end
        close(fd[0]);
    }
}

#include &lt;unistd.h&gt;
#include &lt;fcntl.h&gt;
#include &lt;stdio.h&gt;

int main(){
    int fd = open("output.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);

    if (fd &lt; 0){
        perror("The open() func caused an error on line 6.");
        return 1;
    }

    // use dup2 to redirect stdout to output.txt
    // note that this reassigns the fd for stdout to be our new fd
    // therefore, anything going to stdout will go to the new file instead
    dup2(fd, STDOUT_FILENO); 
    // dup2 is the "sequel" to dup(). 
    // dup() takes a file descriptor and creates a new one (i.e. duplicates)
    // there is also a dup3()....

    close(fd); // we can close the new file descriptor and just point everything to stdout

    // now produce some output
    printf("These are the contents.");
    return 0;
}

To send signals to other processes, we use the kill() function. Despite the name, it isn’t always used to stop another process, it is simply the available funtion to send signals to other processes.
An example follows.
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;unistd.h&gt; // contains kill() to send signals
#include &lt;signal.h&gt; // contains some useful macros, like SIGKILL and SIGTERM
#include &lt;sys/wait.h&gt;

int main(void) {

    pid_t pid = fork();

    if (pid &lt; 0) {
        perror("fork failed");
        exit(1);
    }

    if (pid == 0) {
        // Child process
        printf("Child: PID = %d\n", getpid());

        // a loop that wont stop
        while (1) {
            printf("Child is running...\n");
            sleep(2);
        }
    } else {
        // Parent process
        printf("Parent: PID = %d, Child PID = %d\n", getpid(), pid);

        sleep(5);  // Let the child run for a bit

        printf("Parent: sending SIGTERM to child\n");
        // recall in the parent process pid = child process id
        // use kill() to send signals
        // Using SIGTERM here, but can use SIGKILL also. 
        // SIGKILL is like "Force Quit" (no recovering if needed)
        kill(pid, SIGTERM); 

        // Wait for the child to terminate
        wait(NULL);
        printf("Parent: child has terminated\n");
    }

    return 0;
}

